// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address and an array length and values by passing a bytes blob which we decode into an address[]
    // we need at least one fuzzed parameter; use bytes calldata to let forge fuzz varying sizes and contents
    function testFuzz_property(address from, bytes calldata tosData) public {
        // Construct an address[] from the fuzzed bytes; keep domain wide but require at least one element
        // Interpret tosData as a sequence of 20-byte addresses. If empty, make it length 0 (admissible but rule concerns non-empty case)
        uint256 n = tosData.length / 20;
        // Bound n to a reasonable size to keep gas low but allow >=1
        if (n > 10) n = 10;
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            uint offset = i * 20;
            bytes20 b;
            assembly { b := mload(add(add(tosData.offset, 0x20), offset)) }
            tos[i] = address(b);
        }

        // We will deploy a RecordingCallee that exposes the exact selector transferFrom(address,address,uint256)
        // and will revert if called with an out-of-range index when mutant causes extra iteration.
        // The callee will simply return true (i.e. non-reverting) when called normally.
        RecordingCallee rec = new RecordingCallee();

        // We require the test to observe whether c.transfer returns (ok=true) or reverts (ok=false).
        bool ok;
        // Try-catch the external call to observe revert vs success. We call with the recorded callee address.
        try c.transfer(from, address(rec), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY non-empty tos (n>=1), the reference implementation always returns true (does not revert).
        // The mutant with i<=_tos.length may revert when tos.length>0 due to out-of-bounds access. So assert that
        // when tos has at least one element, c.transfer did not revert (ok == true).
        if (n >= 1) {
            assertTrue(ok);
        } else {
            // If tos is empty, both reference and mutant have require(_tos.length>0) which reverts; we cannot assert success.
            // To keep the assertion universal for admissible non-empty inputs only, we do not assert in the empty case.
            assertTrue(true);
        }
    }
}

// A minimal recording callee that implements the exact function signature
contract RecordingCallee {
    // record number of calls
    uint public calls;
    // expose the exact function so abi.decode works on c's encodeWithSelector
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        return true;
    }
}
